import java.util.*;
public final class TokenCounter {
    private final Map<String, Long> counts = new HashMap<>();
    public static void validate(String token) {
        if (token == null || !token.matches("[a-z]{1,12}")) throw new IllegalArgumentException("Invalid token");
    }
    public synchronized void record(String token) {
        validate(token);
        counts.put(token, counts.getOrDefault(token, 0L) + 1L);
    }
    public synchronized Map<String, Long> snapshot() { return new TreeMap<>(counts); }
}

import java.util.*;
public final class NoteWorker implements Runnable {
    private final TokenCounter counter;
    private final List<String> tokens;
    public NoteWorker(TokenCounter counter, List<String> tokens) {
        this.counter = Objects.requireNonNull(counter);
        this.tokens = List.copyOf(tokens);
        for (String token : this.tokens) TokenCounter.validate(token);
    }
    @Override public void run() { for (String token : tokens) counter.record(token); }
}

import java.util.*;
public final class NoteIndex {
    private NoteIndex() {}
    public static Map<String,Long> count(List<List<String>> batches) throws InterruptedException {
        Objects.requireNonNull(batches);
        if (Thread.interrupted()) throw new InterruptedException("Interrupted before starting workers");
        TokenCounter counter = new TokenCounter();
        List<Thread> workers = new ArrayList<>();
        for (List<String> batch : batches) workers.add(new Thread(new NoteWorker(counter, batch)));
        for (Thread worker : workers) worker.start();
        for (Thread worker : workers) worker.join();
        return counter.snapshot();
    }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
public final class NoteIndexCli {
    private NoteIndexCli() {}
    public static int run(String[] paths, PrintStream out, PrintStream err) throws InterruptedException {
        if (paths.length == 0) { err.println("Usage: NoteIndexCli input..."); return 2; }
        List<List<String>> batches = new ArrayList<>();
        try {
            for (String path : paths) {
                List<String> tokens = new ArrayList<>();
                try (BufferedReader reader = Files.newBufferedReader(Path.of(path), StandardCharsets.UTF_8)) {
                    String line;
                    int number = 0;
                    while ((line = reader.readLine()) != null) {
                        number++;
                        try { TokenCounter.validate(line); }
                        catch (IllegalArgumentException error) { throw new IOException("Invalid token at line " + number, error); }
                        tokens.add(line);
                    }
                }
                batches.add(tokens);
            }
        } catch (IOException | InvalidPathException error) { err.println(error.getMessage()); return 1; }
        Map<String,Long> counts = NoteIndex.count(batches);
        for (Map.Entry<String,Long> entry : counts.entrySet()) out.print(entry.getKey() + "=" + entry.getValue() + "\n");
        return 0;
    }
    public static void main(String[] args) throws InterruptedException { run(args, System.out, System.err); }
}
